const c = $('Configure KPI report').first().json;
const needed = ['reports_dir', 'alerts_path', 'runs_log_path', 'sales_url', 'support_url'];
if (needed.some(k => !String(c[k] || '').trim())) {
  throw new Error('Not set up: fill in reports_dir, alerts_path, runs_log_path, sales_url and support_url in the Config node before running this workflow.');
}
for (const k of ['orders_drop_pct', 'revenue_drop_pct', 'new_tickets_max', 'first_response_max_minutes']) {
  if (typeof c[k] !== 'number' || !isFinite(c[k]) || c[k] <= 0) throw new Error(`Config: ${k} must be a number above 0.`);
}
const tz = String(c.timezone || '').trim() || 'UTC';

// Today's date in the report time zone, written YYYY-MM-DD.
const parts = {};
for (const p of new Intl.DateTimeFormat('en-US', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date())) {
  parts[p.type] = p.value;
}
const today = `${parts.year}-${parts.month}-${parts.day}`;
const shift = (day, n) => {
  const t = new Date(day + 'T12:00:00Z');
  t.setUTCDate(t.getUTCDate() + n);
  return t.toISOString().slice(0, 10);
};
const fail = error => [{ json: { valid: false, error } }];

// A webhook call may name the day to report on (a re-run of a missed day). The schedule always reports on yesterday.
let report_date = shift(today, -1);
if (c.trigger === 'webhook') {
  let body = null;
  try { body = JSON.parse(c.request_body || 'null'); } catch (e) { body = null; }
  const asked = body && typeof body === 'object' && !Array.isArray(body) ? body.report_date : undefined;
  if (asked !== undefined && asked !== null && asked !== '') {
    if (typeof asked !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(asked)) {
      return fail('report_date must be a date written as YYYY-MM-DD, for example 2026-10-20.');
    }
    const t = new Date(asked + 'T12:00:00Z');
    if (isNaN(t.getTime()) || t.toISOString().slice(0, 10) !== asked) return fail(`report_date ${asked} is not a real calendar date.`);
    if (asked >= today) return fail(`report_date must be before today (${today} in ${tz}).`);
    report_date = asked;
  }
}
return [{ json: { valid: true, report_date, prior_date: shift(report_date, -1), today, timezone: tz, trigger: c.trigger } }];

const c = $('Configure KPI report').first().json;
const d = $('Check config and pick date').first().json;

const SOURCES = {
  sales: { label: 'sales', fields: ['orders', 'revenue'] },
  support: { label: 'support', fields: ['new_tickets', 'first_response_minutes'] },
};
const METRICS = [
  { key: 'orders', source: 'sales', label: 'Orders', money: false, rule: 'drop', limit: Number(c.orders_drop_pct) },
  { key: 'revenue', source: 'sales', label: 'Revenue', money: true, rule: 'drop', limit: Number(c.revenue_drop_pct) },
  { key: 'new_tickets', source: 'support', label: 'New support tickets', money: false, rule: 'above', limit: Number(c.new_tickets_max) },
  { key: 'first_response_minutes', source: 'support', label: 'Median first response (minutes)', money: false, rule: 'above', limit: Number(c.first_response_max_minutes) },
];

const isNum = v => typeof v === 'number' && isFinite(v) && v >= 0;
const rowOk = (row, fields) => row && fields.every(f => isNum(row[f]));

// Reads one source's reply. Anything but a usable row for the report date is a gap, never a zero.
function readSource(name, reply) {
  const label = SOURCES[name].label;
  const fields = SOURCES[name].fields;
  const code = Number(reply.statusCode) || 0;
  if (!code) return { ok: false, reason: `no reply from the ${label} API (it timed out after 10 seconds or could not be reached)` };
  if (code !== 200) return { ok: false, reason: `the ${label} API answered HTTP ${code}` };
  let body = reply.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
  if (!body || typeof body !== 'object') return { ok: false, reason: `the ${label} API reply was not JSON` };
  if (!Array.isArray(body.days)) return { ok: false, reason: `the ${label} API reply had no list of days` };
  const day = body.days.find(x => x && x.date === d.report_date);
  if (!day) return { ok: false, reason: `the ${label} API had no numbers for ${d.report_date}` };
  if (!rowOk(day, fields)) return { ok: false, reason: `the ${label} API numbers for ${d.report_date} were missing or not numbers` };
  const prior = body.days.find(x => x && x.date === d.prior_date);
  return { ok: true, day, prior: rowOk(prior, fields) ? prior : null };
}

const src = {
  sales: readSource('sales', $('Get sales numbers').first().json),
  support: readSource('support', $('Get support numbers').first().json),
};

const gaps = [];
for (const name of Object.keys(SOURCES)) {
  const s = src[name];
  if (!s.ok) {
    gaps.push({ source: name, what: 'day', note: `${name === 'sales' ? 'Sales' : 'Support'} numbers are missing: ${s.reason}. They are shown as "missing", not as zero.` });
  } else if (!s.prior) {
    gaps.push({ source: name, what: 'prior_day', note: `${name === 'sales' ? 'Sales' : 'Support'} numbers for ${d.prior_date} are missing, so there is no day-over-day change for them.` });
  }
}

const fmt = (v, money) => v === null || v === undefined ? 'missing'
  : money ? v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : String(v);
const fmtPct = p => p === null ? 'n/a' : (p > 0 ? '+' : '') + p.toFixed(1) + '%';

const metrics = {};
const alerts = [];
for (const m of METRICS) {
  const s = src[m.source];
  const value = s.ok ? s.day[m.key] : null;
  const prior = s.ok && s.prior ? s.prior[m.key] : null;
  // The change is rounded to one decimal, and the alert rule reads that same rounded number.
  const change_pct = value === null || prior === null || prior === 0 ? null : Math.round(((value - prior) / prior) * 1000) / 10;
  let alert = null;
  if (m.rule === 'drop' && change_pct !== null && change_pct <= -m.limit) {
    alert = `${m.label} fell ${fmtPct(change_pct).slice(1)} (from ${fmt(prior, m.money)} to ${fmt(value, m.money)}). Rule: a drop of ${m.limit}% or more from the day before.`;
  }
  if (m.rule === 'above' && value !== null && value > m.limit) {
    alert = `${m.label} was ${fmt(value, m.money)}. Rule: above ${m.limit}.`;
  }
  metrics[m.key] = { value, prior, change_pct };
  if (alert) alerts.push({ metric: m.key, message: alert, value, prior, change_pct });
}

const nice = day => new Date(day + 'T12:00:00Z').toLocaleDateString('en-US', { timeZone: 'UTC', weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });
const short = day => new Date(day + 'T12:00:00Z').toLocaleDateString('en-US', { timeZone: 'UTC', month: 'short', day: 'numeric' });
const flagged = gaps.length > 0;
const made = new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC';

const md = [];
md.push(`# Daily KPI report for ${nice(d.report_date)}`, '');
md.push(flagged ? 'Status: FLAGGED. Some numbers are missing. Read the gap notes before using this report.'
                : 'Status: OK. All numbers are in.');
md.push('');
md.push(`Compared with ${nice(d.prior_date)}. Made ${made} by the ${d.trigger} run.`, '');
md.push(`| Metric | ${short(d.report_date)} | ${short(d.prior_date)} | Change | Alert |`);
md.push('|---|---:|---:|---:|---|');
for (const m of METRICS) {
  const x = metrics[m.key];
  md.push(`| ${m.label} | ${fmt(x.value, m.money)} | ${fmt(x.prior, m.money)} | ${fmtPct(x.change_pct)} | ${alerts.some(a => a.metric === m.key) ? 'ALERT' : ''} |`);
}
md.push('', '## Alerts', '');
if (alerts.length) for (const a of alerts) md.push(`- ${a.message}`); else md.push('- None.');
md.push('', '## Gaps', '');
if (gaps.length) for (const g of gaps) md.push(`- ${g.note}`); else md.push('- None.');
md.push('');

return [{ json: {
  report_date: d.report_date, prior_date: d.prior_date, trigger: d.trigger,
  flagged, gaps, alerts, metrics, markdown: md.join('\n'),
} }];

const fs = require('fs');
const path = require('path');
const c = $('Configure KPI report').first().json;
const r = $input.first().json;
const at = new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
const fileName = `kpi-report-${r.report_date}.md`;
const file = path.join(c.reports_dir, fileName);
const tmp = path.join(c.reports_dir, `.${fileName}.tmp-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
const failed = (step, e) => [{ json: { saved: false, error: `${step} could not be written (${e.code || e.message})` } }];

// 1. The report. Written to a temporary file, then renamed, so a reader never sees half a report.
try {
  fs.writeFileSync(tmp, r.markdown);
  fs.renameSync(tmp, file);
} catch (e) {
  try { fs.unlinkSync(tmp); } catch (e2) { /* nothing to clean up */ }
  return failed('the report', e);
}

// 2. Alert lines: one per threshold crossed and one per gap. A re-run for the same day does not repeat a line.
const entries = [
  ...r.alerts.map(a => ({ key: `${r.report_date}|threshold|${a.metric}`, line: {
    at, report_date: r.report_date, kind: 'threshold', metric: a.metric, value: a.value, prior: a.prior,
    change_pct: a.change_pct, message: a.message } })),
  ...r.gaps.map(g => ({ key: `${r.report_date}|gap|${g.source}|${g.what}`, line: {
    at, report_date: r.report_date, kind: 'gap', source: g.source, what: g.what, message: g.note } })),
];
let newLines = 0;
try {
  const seen = new Set();
  if (fs.existsSync(c.alerts_path)) {
    for (const text of fs.readFileSync(c.alerts_path, 'utf8').split('\n')) {
      if (!text.trim()) continue;
      try {
        const o = JSON.parse(text);
        seen.add(o.kind === 'gap' ? `${o.report_date}|gap|${o.source}|${o.what}` : `${o.report_date}|threshold|${o.metric}`);
      } catch (e) { /* a line that is not JSON is left alone */ }
    }
  }
  const fresh = entries.filter(x => !seen.has(x.key));
  if (fresh.length) fs.appendFileSync(c.alerts_path, fresh.map(x => JSON.stringify(x.line)).join('\n') + '\n');
  newLines = fresh.length;
} catch (e) {
  return failed('the alert lines', e);
}

// 3. One run line.
const status = r.flagged ? 'flagged' : 'ok';
const gapList = [...new Set(r.gaps.map(g => g.source))].join(',') || 'none';
try {
  fs.appendFileSync(c.runs_log_path,
    `${at} trigger=${r.trigger} report_date=${r.report_date} status=${status} gaps=${gapList} alerts=${r.alerts.length} new_alert_lines=${newLines} report=${fileName}\n`);
} catch (e) {
  return failed('the run line', e);
}

return [{ json: { saved: true, reply: {
  ok: true, report_date: r.report_date, prior_date: r.prior_date, trigger: r.trigger, flagged: r.flagged,
  gaps: r.gaps.map(g => ({ source: g.source, what: g.what, note: g.note })),
  alerts: r.alerts.map(a => ({ metric: a.metric, message: a.message, change_pct: a.change_pct, value: a.value })),
  new_alert_lines: newLines, report_file: fileName, metrics: r.metrics,
} } }];
